/**
 * The footer of DashboardShell: the copyright and a row of links, under the content column (inset) or across the
 * whole shell (full).
 */
import { For, type JSX } from "solid-js";
import { Block, List, ListItem, Text } from "../compose";
import { MenuEntry } from "../components/menu-entry";
import { NavBlock } from "../components/nav-block";
import { cn, tpl, uniqLabel } from "../utils";
import type { ShellNav } from "../blocks/dashboard-shell.types";

export type ShellFooterProps = {
  nav: ShellNav;
  place?: "full" | "inset";
  landmarkLabel?: string;
};

export function ShellFooter({ nav, place = "full", landmarkLabel }: ShellFooterProps) {
  return (
    <Block
      tag="footer"
      class={cn(
        "flex shrink-0 flex-wrap items-center justify-between gap-4 border-t border-border px-6 py-4",
        (((place as string) === "full") ? "bg-card" : "")
      )}
      data-testid="footer"
      data-place={place}
      aria-label={landmarkLabel}
    >
      <Text size="xs" class="text-muted-foreground">
        {nav.copyright}
      </Text>
      {((nav.footer?.length ?? 0) > 0) ? (
        <NavBlock
          label={
            landmarkLabel ? uniqLabel(tpl("{0}, {1}", nav.footerLabel, landmarkLabel))
            : nav.footerLabel
          }
        >
          <List class="m-0 flex list-none items-center gap-4 p-0">
            <For each={nav.footer ?? []}>{(f) => (
              <ListItem>
                <MenuEntry href={f.href} class="text-xs text-muted-foreground" variant="muted" size="sm">
                  {f.name}
                </MenuEntry>
              </ListItem>
            )}</For>
          </List>
        </NavBlock>
      ) : null}
    </Block>
  );
